script:
frappe.ui.form.on('Project', {
	refresh(frm) {
		dinext_project_evaluation_project_scoring.refresh(frm);
	}
});

const dinext_project_evaluation_project_scoring = {
	refresh(frm) {
		if (frm.is_new()) return;

		frm.add_custom_button(__('Create Scorecard'), () => this.create_scorecard(frm), __('Evaluation'));
		frm.add_custom_button(__('Open Scorecards'), () => {
			frappe.set_route('List', 'Project Scorecard', { project: frm.doc.name });
		}, __('Evaluation'));
		frm.add_custom_button(__('Open Scoring Report'), () => {
			frappe.route_options = {
				project_portfolio: frm.doc.custom_project_portfolio,
				project: [frm.doc.name]
			};
			frappe.set_route('query-report', 'Project Scoring Report');
		}, __('Evaluation'));

		this.render_history(frm);
	},

	create_scorecard(frm) {
		frappe.prompt([
			{
				fieldname: 'profile',
				label: __('Scoring Profile'),
				fieldtype: 'Link',
				options: 'Project Scoring Profile',
				reqd: 1,
				get_query() {
					const filters = { status: 'Active' };
					if (frm.doc.custom_project_portfolio) filters.portfolio = ['in', [frm.doc.custom_project_portfolio, '']];
					return { filters };
				}
			}
		], (values) => {
			frappe.call({
				method: 'dinext_project_evaluation.api.create_scorecard',
				args: { project: frm.doc.name, profile: values.profile },
				callback(r) {
					if (r.message && r.message.name) {
						frappe.set_route('Form', 'Project Scorecard', r.message.name);
					}
				}
			});
		}, __('Create Project Scorecard'), __('Create'));
	},

	render_history(frm) {
		frappe.call({
			method: 'dinext_project_evaluation.api.get_scorecard_history',
			args: { project: frm.doc.name, limit: 5 },
			callback(r) {
				const rows = r.message || [];
				if (!rows.length) return;

				const html = rows.map((row) => {
					const score = row.integral_score === null || row.integral_score === undefined ? '-' : flt(row.integral_score, 4);
					const gate = row.gate_pass ? __('Gate passed') : __('Gate failed');
					return `<li><a href="/app/project-scorecard/${encodeURIComponent(row.name)}">${frappe.utils.escape_html(row.name)}</a>: ${score} (${gate})</li>`;
				}).join('');

				frm.dashboard.add_section(`<div class="project-scoring-history"><h5>${__('Project Evaluation')}</h5><ul>${html}</ul></div>`);
			}
		});
	}
};

frappe.ui.form.on('Project Portfolio', {
	refresh(frm) {
		if (frm.is_new()) return;

		frm.add_custom_button(__('Project Scoring Report'), () => {
			frappe.route_options = { project_portfolio: frm.doc.name };
			frappe.set_route('query-report', 'Project Scoring Report');
		}, __('Evaluation'));

		frm.add_custom_button(__('Bubble Chart'), () => {
			frappe.route_options = {
				project_portfolio: frm.doc.name,
				x_axis: 'risk_score',
				y_axis: 'integral_score'
			};
			frappe.set_route('query-report', 'Project Scoring Report');
		}, __('Evaluation'));
	}
});
